%[text] # Week 4 Practical Activity: Identify and Validate Coupled-Oscillator Modes
%[text] **PRACTICAL ACTIVITY.** This group investigation assesses model formulation, matrix construction, generalized eigenproblems, physical interpretation of mode shapes, numerical validation, controlled parameter changes, and capstone-question selection. Producing a long program is not the goal.
%[text] **Physical question.** How do coupling strength and broken symmetry change the natural frequencies and mode shapes of a two-mass oscillator?
%[text] **Working arrangement.** Complete the Week 04 Individual Practical Check — Quiz in Google Classroom before discussing the problem or using MATLAB, notes, calculators, or AI. Then work in a group of two or three. MATLAB Copilot may be used during group work, but every material suggestion must be declared and independently tested.
%%
%[text] ## Complete the Individual Check First
%[text] Each student submits the Week 04 Individual Practical Check — Quiz from Google Classroom before group work begins. The lecturer will confirm when the quiz is available. Do not duplicate those answers here.
%%
%[text] ## Group Record and Role Rotation
%[text] Record all members and assign model, implementation, and validation leads. Rotate roles from earlier practicals.
groupMembers = "TODO: names and matric numbers" %[output:24d6832a]
roleRecord = "TODO: identify the model, implementation, and validation leads" %[output:72c6ef9d]
%%
%[text] ## Predict Before Computing
%[text] Two equal masses are attached to identical outer springs and connected by a coupling spring. Predict the relative motion of the two masses in the lower- and higher-frequency modes. Then predict what happens to both frequencies when the coupling spring becomes stiffer.
predictionRecord = "TODO: lower mode, higher mode, frequency ordering, coupling-strength prediction, and physical reason" %[output:9e7dad74]
%%
%[text] ## Draw the Model and State Assumptions
%[text] Sketch wall--spring--mass--coupling spring--mass--spring--wall. Label $m\_1$, $m\_2$, $k$, $k\_c$, $x\_1$, and $x\_2$. State the small-oscillation assumptions and the displacement sign convention.
modelRecord = "TODO: labelled sketch reference, coordinate directions, equilibrium reference, and assumptions" %[output:332a7e15]
%%
%[text] ## Derive the Equations Before the Matrices
%[text] For the symmetric baseline with $m\_1=m\_2=m$, derive Newton's-law equations and show that they can be written as $\\mathbf{M}\\ddot{\\mathbf{x}}+\\mathbf{K}\\mathbf{x}=0$. Do not assemble matrices until every force term and sign has a physical origin.
derivationRecord = "TODO: both signed equations of motion and their matrix form" %[output:69d73800]
unitRecord = "TODO: explain the units of M, K, lambda, omega, and frequency" %[output:67d08428]
%%
%[text] ## Baseline Parameters and Matrix Assembly
%[text] Use $m\_1=m\_2=0.50\\,\\mathrm{kg}$, $k=20\\,\\mathrm{N\\,m^{-1}}$, and $k\_c=10\\,\\mathrm{N\\,m^{-1}}$. Assemble the generalized eigenproblem $\\mathbf{K}\\boldsymbol{\\phi}=\\lambda\\mathbf{M}\\boldsymbol{\\phi}$.
m1_kg = 0.50;
m2_kg = 0.50;
k_Npm = 20.0;
kc_Npm = 10.0;
M_kg = diag([m1_kg m2_kg]);
K_Npm = [k_Npm+kc_Npm, -kc_Npm; -kc_Npm, k_Npm+kc_Npm];
parameterRecord = table(m1_kg,m2_kg,k_Npm,kc_Npm) %[output:3ec021c4]
matrixRecord = "TODO: explain why the diagonal and off-diagonal K entries have these values and signs" %[output:1c05b53b]
assert(issymmetric(M_kg) && issymmetric(K_Npm),'The baseline conservative matrices should be symmetric.')
%%
%[text] ## Solve and Sort the Eigenpairs
%[text] Use `eig(K_Npm,M_kg)`, sort the eigenvalues in ascending order, and keep each eigenvector paired with its eigenvalue. Convert $\\lambda$ to angular frequency and hertz using $\\omega=\\sqrt{\\lambda}$ and $f=\\omega/(2\\pi)$.
[modeRaw,eigenvalueMatrix_per_s2] = eig(K_Npm,M_kg);
[eigenvalue_per_s2,sortIndex] = sort(diag(eigenvalueMatrix_per_s2));
modeRaw = modeRaw(:,sortIndex);
omega_radps = sqrt(eigenvalue_per_s2);
frequency_Hz = omega_radps/(2*pi);
frequencyRecord = table((1:2)',eigenvalue_per_s2,omega_radps,frequency_Hz, ... %[output:group:77cd16e4] %[output:48b9221b]
    'VariableNames',{'Mode','Lambda_per_s2','Omega_radps','Frequency_Hz'}) %[output:group:77cd16e4] %[output:48b9221b]
frequencyInterpretation = "TODO: compare the frequency ordering with the prediction and explain why lambda itself is not measured in Hz" %[output:2b51b7bc]
%%
%[text] ## Normalize and Interpret the Mode Shapes
%[text] Normalize each mode so the largest displacement magnitude is one. Remember that multiplying an eigenvector by any nonzero constant, including $-1$, does not create a new physical mode.
modeShape = modeRaw;
for modeIndex = 1:2
    modeShape(:,modeIndex) = modeShape(:,modeIndex)/max(abs(modeShape(:,modeIndex)));
    if modeShape(1,modeIndex) < 0
        modeShape(:,modeIndex) = -modeShape(:,modeIndex);
    end
end
modeShapeRecord = array2table(modeShape,'VariableNames',{'Mode1','Mode2'},'RowNames',{'Mass1','Mass2'}) %[output:6ccffefe]
modeInterpretation = "TODO: identify in-phase/out-of-phase motion, coupling-spring deformation, and why the modes have different frequencies" %[output:38314bcd]
%%
%[text] ## Validate Against the Symmetric Analytic Result
%[text] For identical masses and outer springs, symmetry predicts $\\lambda\_1=k/m$ and $\\lambda\_2=(k+2k\_c)/m$. Compare the numerical and analytic frequencies quantitatively.
analyticLambda_per_s2 = [k_Npm/m1_kg; (k_Npm+2*kc_Npm)/m1_kg];
analyticFrequency_Hz = sqrt(analyticLambda_per_s2)/(2*pi);
relativeFrequencyError = abs(frequency_Hz-analyticFrequency_Hz)./analyticFrequency_Hz;
assert(all(relativeFrequencyError < 1e-12),'The baseline eigenfrequencies disagree with the analytic symmetric reference.')
analyticValidationRecord = table(frequency_Hz,analyticFrequency_Hz,relativeFrequencyError) %[output:1fe9d317]
analyticValidationExplanation = "TODO: state what this analytic agreement checks and what it does not prove" %[output:3730394f]
%%
%[text] ## Validate the Eigen-Equation Residual
%[text] Evaluate $\\mathbf{K}\\boldsymbol{\\phi}-\\lambda\\mathbf{M}\\boldsymbol{\\phi}$ for each mode and calculate a scaled residual. Explain why this is an algebraic check of the assembled matrices rather than complete physical validation.
scaledEigenResidual = zeros(2,1);
for modeIndex = 1:2
    phi = modeRaw(:,modeIndex);
    lambda = eigenvalue_per_s2(modeIndex);
    residual = K_Npm*phi-lambda*M_kg*phi;
    scaledEigenResidual(modeIndex) = norm(residual,2)/(norm(K_Npm,2)*norm(phi,2)+abs(lambda)*norm(M_kg,2)*norm(phi,2));
end
assert(all(scaledEigenResidual < 1e-14),'An eigen-equation residual is unexpectedly large.')
residualRecord = table((1:2)',scaledEigenResidual,'VariableNames',{'Mode','ScaledEigenResidual'}) %[output:061df0e5]
residualExplanation = "TODO: state what this evidence can and cannot establish" %[output:4d494fd2]
%%
%[text] ## Validate Mass Orthogonality
%[text] Mass-normalize the two eigenvectors and check $\\boldsymbol{\\Phi}^T\\mathbf{M}\\boldsymbol{\\Phi}\\approx\\mathbf{I}$. Explain why this property is expected for distinct modes of the symmetric conservative system.
modeMassNormalized = modeRaw;
for modeIndex = 1:2
    phi = modeMassNormalized(:,modeIndex);
    modeMassNormalized(:,modeIndex) = phi/sqrt(phi'*M_kg*phi);
end
massOrthogonality = modeMassNormalized'*M_kg*modeMassNormalized;
assert(norm(massOrthogonality-eye(2),inf) < 1e-12,'Mass-normalized baseline modes are not orthonormal as expected.')
orthogonalityRecord = array2table(massOrthogonality, ... %[output:group:6e633943] %[output:0e026998]
    'VariableNames',{'Mode1','Mode2'},'RowNames',{'Mode1','Mode2'}) %[output:group:6e633943] %[output:0e026998]
orthogonalityExplanation = "TODO: interpret the diagonal and off-diagonal entries" %[output:8f409de8]
%%
%[text] ## Controlled Investigation: Change Coupling Strength
%[text] Predict before every change. Evaluate $k\_c=0$, $5$, $10$, $20$, and $40\\,\\mathrm{N\\,m^{-1}}$. Record both frequencies and explain which mode is sensitive to coupling and why.
couplingValues_Npm = [0;5;10;20;40];
couplingFrequency_Hz = zeros(numel(couplingValues_Npm),2);
for sweepIndex = 1:numel(couplingValues_Npm)
    kc = couplingValues_Npm(sweepIndex);
    K_sweep_Npm = [k_Npm+kc, -kc; -kc, k_Npm+kc];
    lambdaSweep_per_s2 = sort(eig(K_sweep_Npm,M_kg));
    couplingFrequency_Hz(sweepIndex,:) = (sqrt(lambdaSweep_per_s2)/(2*pi))';
end
couplingTable = table(couplingValues_Npm,couplingFrequency_Hz(:,1),couplingFrequency_Hz(:,2), ... %[output:group:98884501] %[output:3f7c3255]
    'VariableNames',{'Coupling_Npm','Mode1_Hz','Mode2_Hz'}) %[output:group:98884501] %[output:3f7c3255]
plot(couplingValues_Npm,couplingFrequency_Hz,'-o','LineWidth',1.5) %[output:15e8b53a]
xlabel('Coupling stiffness k_c (N/m)') %[output:15e8b53a]
ylabel('Natural frequency (Hz)') %[output:15e8b53a]
title('Effect of coupling stiffness') %[output:15e8b53a]
legend('Mode 1','Mode 2','Location','best') %[output:15e8b53a]
grid on %[output:15e8b53a]
couplingInvestigationRecord = "TODO: predictions, evidence, physical explanation, and the zero-coupling limiting case" %[output:0cedcee3]
%%
%[text] ## Controlled Investigation: Break the Mass Symmetry
%[text] Keep $m\_1=0.50\\,\\mathrm{kg}$ and change $m\_2$ to $0.75\\,\\mathrm{kg}$. Recompute the eigenpairs. Do not expect exact $\[1,1\]^T$ and $\[1,-1\]^T$ shapes after symmetry is broken.
m2_asymmetric_kg = 0.75;
M_asymmetric_kg = diag([m1_kg m2_asymmetric_kg]);
[modeAsymmetricRaw,eigenvalueAsymmetricMatrix_per_s2] = eig(K_Npm,M_asymmetric_kg);
[eigenvalueAsymmetric_per_s2,asymmetricSortIndex] = sort(diag(eigenvalueAsymmetricMatrix_per_s2));
modeAsymmetricRaw = modeAsymmetricRaw(:,asymmetricSortIndex);
frequencyAsymmetric_Hz = sqrt(eigenvalueAsymmetric_per_s2)/(2*pi);
modeAsymmetric = modeAsymmetricRaw;
for modeIndex = 1:2
    modeAsymmetric(:,modeIndex) = modeAsymmetric(:,modeIndex)/max(abs(modeAsymmetric(:,modeIndex)));
    if modeAsymmetric(1,modeIndex) < 0
        modeAsymmetric(:,modeIndex) = -modeAsymmetric(:,modeIndex);
    end
end
asymmetricFrequencyRecord = table((1:2)',frequencyAsymmetric_Hz, ... %[output:group:1e4cc3ac] %[output:0c94dbf6]
    'VariableNames',{'Mode','Frequency_Hz'}) %[output:group:1e4cc3ac] %[output:0c94dbf6]
asymmetricModeShapeRecord = array2table(modeAsymmetric, ... %[output:group:1e705b52] %[output:701443a0]
    'VariableNames',{'Mode1','Mode2'},'RowNames',{'Mass1','Mass2'}) %[output:group:1e705b52] %[output:701443a0]
asymmetryInterpretation = "TODO: compare with the symmetric baseline and explain how unequal inertia changes frequency and relative amplitudes" %[output:558080f1]
%%
%[text] ## Validate the Asymmetric Case Without the Symmetric Formula
%[text] The simple symmetric analytic formula no longer applies. Use different evidence: scaled eigen-equation residuals, mass orthogonality, positive squared frequencies, and the limiting expectation that increasing one mass should tend to reduce at least the lower frequency.
asymmetricScaledResidual = zeros(2,1);
for modeIndex = 1:2
    phi = modeAsymmetricRaw(:,modeIndex);
    lambda = eigenvalueAsymmetric_per_s2(modeIndex);
    residual = K_Npm*phi-lambda*M_asymmetric_kg*phi;
    asymmetricScaledResidual(modeIndex) = norm(residual,2)/(norm(K_Npm,2)*norm(phi,2)+abs(lambda)*norm(M_asymmetric_kg,2)*norm(phi,2));
end
modeAsymmetricMassNormalized = modeAsymmetricRaw;
for modeIndex = 1:2
    phi = modeAsymmetricMassNormalized(:,modeIndex);
    modeAsymmetricMassNormalized(:,modeIndex) = phi/sqrt(phi'*M_asymmetric_kg*phi);
end
asymmetricMassOrthogonality = modeAsymmetricMassNormalized'*M_asymmetric_kg*modeAsymmetricMassNormalized;
assert(all(asymmetricScaledResidual < 1e-14),'An asymmetric eigen-equation residual is unexpectedly large.')
assert(norm(asymmetricMassOrthogonality-eye(2),inf) < 1e-12,'Asymmetric mass-normalized modes are not orthonormal as expected.')
assert(frequencyAsymmetric_Hz(1) < frequency_Hz(1),'Increasing one mass should reduce the lower frequency for this parameter change.')
asymmetricValidationRecord = table(asymmetricScaledResidual, ... %[output:group:9d37637c] %[output:40bbd6e0]
    'VariableNames',{'ScaledEigenResidual'}) %[output:group:9d37637c] %[output:40bbd6e0]
